
import React, { useEffect, useState } from "react";
import axios from "axios";

const YANDEX_API_KEY = "dict.1.1.20261022T164044Z.9b8ade2173cd4883.b1bb0f5df85ce64ac06391447a748c8f0e3f84b3";

export default function Translate({ language, text }) {
  const [translated, setTranslated] = useState("");

  useEffect(() => {
    if (!text.trim()) {
      setTranslated("");
      return;
    }

    let active = true;

    const translate = async () => {
      try {
        const { data } = await axios.get(
          "https://dictionary.yandex.net/api/v1/dicservice.json/lookup",
          {
            params: {
              key: YANDEX_API_KEY,
              lang: "ru-en",
              text: text.trim(),
              ui: "ru"
            }
          }
        );

        const word = data.def?.[0]?.tr?.[0]?.text || "";

        if (active) {
          setTranslated(word);
        }
      } catch (error) {
        console.error("Ошибка Yandex Dictionary API:", error);
        if (active) {
          setTranslated("");
        }
      }
    };

    translate();

    return () => {
      active = false;
    };
  }, [text, language]);

  return <h1 className="title">{translated}</h1>;
}